import base64
import io
import os
import sqlite3
from datetime import datetime
from PIL import Image, ImageDraw, ImageFont

# All output (tokens.db + receipt images) is saved here, inside the
# current user's home folder - e.g. C:\Users\malleshy\TokenReceipts on
# Windows, or /home/malleshy/TokenReceipts on Linux/Mac - regardless of
# which folder you run the script from.
# On cloud platforms set the TOKEN_DIR environment variable to a writable path.
SAVE_DIR = os.environ.get(
    "TOKEN_DIR",
    os.path.join(os.path.expanduser("~"), "TokenReceipts")
)
os.makedirs(SAVE_DIR, exist_ok=True)

DB_FILE = os.path.join(SAVE_DIR, "tokens.db")

# To use a DIFFERENT logo than the one built into this script, place a
# PNG or JPG file named exactly "logo_override.jpg" (or .png) inside the
# TokenReceipts folder (SAVE_DIR) - it will be used automatically instead.
LOGO_OVERRIDE_PATHS = [
    os.path.join(SAVE_DIR, "logo_override.jpg"),
    os.path.join(SAVE_DIR, "logo_override.png"),
]

# Colors used for the receipt graphic (maroon, matching the logo)
ACCENT_COLOR = (122, 20, 20)
TEXT_COLOR = (40, 40, 40)
LINE_COLOR = (225, 225, 225)
FOOTER_COLOR = (130, 130, 130)

# The Gadi Maisamma Youth, Yerrambelly logo, embedded so the script works
# out of the box with no extra files to manage.
DEFAULT_LOGO_B64 = ""


# ---------------------------------------------------------------------------
# Database helpers  (SQLite — no extra package needed, built into Python)
# ---------------------------------------------------------------------------

def _db_conn():
    """Open a connection to the SQLite database with row-factory enabled."""
    conn = sqlite3.connect(DB_FILE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    """Create the tokens table if it doesn't exist yet. Call once at startup.
    Uses AUTOINCREMENT so the DB assigns token numbers atomically — safe for
    concurrent requests even across multiple server processes.
    """
    with _db_conn() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS tokens (
                token_no  INTEGER PRIMARY KEY AUTOINCREMENT,
                name      TEXT    NOT NULL,
                phone     TEXT    NOT NULL,
                timestamp TEXT    NOT NULL
            )
        """)
        conn.commit()


def get_next_token_number():
    """Returns what the next token number will be (for display only)."""
    with _db_conn() as conn:
        row = conn.execute("SELECT MAX(token_no) FROM tokens").fetchone()
        max_no = row[0]
        return 1 if max_no is None else int(max_no) + 1


def save_token(name, phone):
    """Insert a new token — DB assigns the token_no atomically via AUTOINCREMENT.
    Returns (token_no, timestamp) so the caller knows the assigned number.
    Safe for concurrent requests: no race condition possible."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with _db_conn() as conn:
        cursor = conn.execute(
            "INSERT INTO tokens (name, phone, timestamp) VALUES (?, ?, ?)",
            (name, phone, timestamp),
        )
        token_no = cursor.lastrowid   # DB-assigned, guaranteed unique
        conn.commit()
    return token_no, timestamp


def lookup_token(token_no):
    """Return a record dict for the given token number, or None if not found."""
    with _db_conn() as conn:
        row = conn.execute(
            "SELECT token_no, name, phone, timestamp FROM tokens WHERE token_no = ?",
            (int(token_no),),
        ).fetchone()
    if row:
        return {"token": str(row["token_no"]), "name": row["name"],
                "phone": row["phone"], "timestamp": row["timestamp"]}
    return None


def get_font(bold=False, italic=False, size=16):
    """Tries common system fonts across Windows/Mac/Linux; falls back to Pillow's
    built-in font so the script never crashes if none of them are installed."""
    if italic:
        candidates = ["ariali.ttf", "Arial Italic.ttf", "DejaVuSans-Oblique.ttf"]
    elif bold:
        candidates = ["arialbd.ttf", "Arial Bold.ttf", "DejaVuSans-Bold.ttf"]
    else:
        candidates = ["arial.ttf", "Arial.ttf", "DejaVuSans.ttf"]

    for name in candidates:
        try:
            return ImageFont.truetype(name, size)
        except OSError:
            continue

    try:
        return ImageFont.load_default(size=size)
    except TypeError:
        return ImageFont.load_default()


def load_logo(size):
    """Loads the organization's logo: an override file if one is present,
    otherwise the logo built into this script. Returns a square RGBA image."""
    for path in LOGO_OVERRIDE_PATHS:
        if os.path.exists(path):
            try:
                return Image.open(path).convert("RGBA").resize((size, size))
            except Exception:
                pass

    try:
        raw = base64.b64decode(DEFAULT_LOGO_B64)
        return Image.open(io.BytesIO(raw)).convert("RGBA").resize((size, size))
    except Exception:
        return None


def build_receipt_image(token_no, name, phone, timestamp, filename):
    """Draws a clean, professional-looking receipt and saves it as a PNG image."""
    width, height = 520, 470
    img = Image.new("RGB", (width, height), "white")
    draw = ImageDraw.Draw(img)

    subtitle_font = get_font(bold=True, size=18)
    token_font = get_font(bold=True, size=28)
    label_font = get_font(bold=True, size=16)
    value_font = get_font(size=16)
    footer_font = get_font(italic=True, size=12)

    def centered_text(y, text, font, fill):
        bbox = draw.textbbox((0, 0), text, font=font)
        x = (width - (bbox[2] - bbox[0])) / 2
        draw.text((x, y), text, font=font, fill=fill)

    # Outer border
    draw.rectangle([4, 4, width - 5, height - 5], outline=ACCENT_COLOR, width=3)

    # Logo (already contains the organization name)
    logo_size = 150
    logo_top = 15
    logo = load_logo(logo_size)
    if logo is not None:
        img.paste(logo, (int(width / 2 - logo_size / 2), logo_top), logo)

    # Subtitle + token number
    subtitle_y = logo_top + logo_size + 15
    centered_text(subtitle_y, "TOKEN RECEIPT", subtitle_font, ACCENT_COLOR)
    centered_text(subtitle_y + 32, f"TOKEN NO. {token_no}", token_font, ACCENT_COLOR)

    line_y = subtitle_y + 32 + 55
    draw.line([35, line_y, width - 35, line_y], fill=LINE_COLOR, width=2)

    rows = [("Name", name), ("Phone No", phone), ("Date/Time", timestamp)]
    y = line_y + 25
    for label, value in rows:
        draw.text((45, y), f"{label} :", font=label_font, fill=TEXT_COLOR)
        draw.text((185, y), value, font=value_font, fill=TEXT_COLOR)
        y += 42

    draw.line([35, y + 5, width - 35, y + 5], fill=LINE_COLOR, width=2)
    centered_text(height - 40, "Please keep this receipt safe.", footer_font, FOOTER_COLOR)

    img.save(filename)


def build_receipt_image_bytes(token_no, name, phone, timestamp):
    """Same as build_receipt_image() but returns PNG bytes instead of saving to disk.
    Used by the web app so receipt images work on cloud platforms with no persistent disk."""
    buf = io.BytesIO()
    # Reuse the drawing logic by temporarily redirecting to a buffer
    width, height = 520, 470
    img = Image.new("RGB", (width, height), "white")
    draw = ImageDraw.Draw(img)

    subtitle_font = get_font(bold=True, size=18)
    token_font = get_font(bold=True, size=28)
    label_font = get_font(bold=True, size=16)
    value_font = get_font(size=16)
    footer_font = get_font(italic=True, size=12)

    def centered_text(y, text, font, fill):
        bbox = draw.textbbox((0, 0), text, font=font)
        x = (width - (bbox[2] - bbox[0])) / 2
        draw.text((x, y), text, font=font, fill=fill)

    draw.rectangle([4, 4, width - 5, height - 5], outline=ACCENT_COLOR, width=3)

    logo_size = 150
    logo_top = 15
    logo = load_logo(logo_size)
    if logo is not None:
        img.paste(logo, (int(width / 2 - logo_size / 2), logo_top), logo)

    subtitle_y = logo_top + logo_size + 15
    centered_text(subtitle_y, "TOKEN RECEIPT", subtitle_font, ACCENT_COLOR)
    centered_text(subtitle_y + 32, f"TOKEN NO. {token_no}", token_font, ACCENT_COLOR)

    line_y = subtitle_y + 32 + 55
    draw.line([35, line_y, width - 35, line_y], fill=LINE_COLOR, width=2)

    rows = [("Name", name), ("Phone No", phone), ("Date/Time", timestamp)]
    y = line_y + 25
    for label, value in rows:
        draw.text((45, y), f"{label} :", font=label_font, fill=TEXT_COLOR)
        draw.text((185, y), value, font=value_font, fill=TEXT_COLOR)
        y += 42

    draw.line([35, y + 5, width - 35, y + 5], fill=LINE_COLOR, width=2)
    centered_text(height - 40, "Please keep this receipt safe.", footer_font, FOOTER_COLOR)

    img.save(buf, format="PNG")
    buf.seek(0)
    return buf


def print_receipt(token_no, name, phone):
    """Prints a plain-text version to the console and saves the graphical receipt as a PNG."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    print("\n--- Token Generated ---")
    print(f"Token No : {token_no}")
    print(f"Name     : {name}")
    print(f"Phone No : {phone}")
    print(f"Date/Time: {timestamp}")
    print("------------------------")

    image_filename = os.path.join(SAVE_DIR, f"receipt_{token_no}.png")
    build_receipt_image(token_no, name, phone, timestamp, image_filename)
    print(f"(Receipt image saved as {image_filename})\n")


def generate_token():
    name = input("Enter your name: ").strip()
    phone = input("Enter your phone number: ").strip()

    if not name:
        print("Name cannot be empty.")
        return
    if not phone.isdigit() or len(phone) < 10:
        print("Please enter a valid phone number (digits only, at least 10 digits).")
        return

    token_no = get_next_token_number()
    save_token(token_no, name, phone)
    print_receipt(token_no, name, phone)


if __name__ == "__main__":
    while True:
        generate_token()
        again = input("Generate another token? (y/n): ").strip().lower()
        if again != "y":
            break
